functions.eliTeamTokens:
function eliTeamTokens(speed, theme) {
  var x = speed && speed > 0 ? speed : 1;
  var PALETTES = {
    light: {
      panel: "#f5f7fa", surface: "#ffffff", ink: "#0f1f3d", mute: "#64748b", faint: "#9aa8bb", line: "#d6dee9",
      navy: "#13294b", navyTop: "#1d3a69", navyBottom: "#0d1d3a", gold: "#c9a227", goldPale: "#e5cc80", goldInk: "#8a6a00",
      idleFill: "#ffffff", tint: "#fbf6e4", shadow: "rgba(10,22,48,.12)", pop: "#ffffff", chartGlow: "#ffffff",
      // an agent's proposed redline: ELI's green, as on the review cards (owner: green = ELI proposes, red = already in Word)
      prop: "#15803d", propFill: "#e8f6ec", propDel: "#b42318", propDelFill: "#fdecec",   // additions green, deletions red
    },
    dark: {
      panel: "#0c1a36", surface: "#11244a", ink: "#f1f4f9", mute: "#9aa9c2", faint: "#5d7091", line: "#26406b",
      navy: "#13294b", navyTop: "#24467f", navyBottom: "#0b1830", gold: "#c9a227", goldPale: "#e5cc80", goldInk: "#e5cc80",
      idleFill: "#122a52", tint: "#17325e", shadow: "rgba(0,0,0,.4)", pop: "#1b3563", chartGlow: "#1c3b70",
      prop: "#6fcf8f", propFill: "rgba(46,160,90,.18)", propDel: "#f3a197", propDelFill: "rgba(180,35,24,.22)",
    },
  };
  var th = theme === "dark" ? "dark" : "light";
  return {
    theme: th,
    color: PALETTES[th],
    size: {
      // chart units; the chart is 400 wide and scales to the pane
      lead: 18, senior: 16, spec: 13, asst: 8,     // seal radius
      leadY: 30, busY: 56, specY: 76, nameGap: 13, specSpread: 96,
      asstY: 128, asstStep: 21, asstX: -26, spineX: -38, asstName: 11,   // assistants: a column under the specialist, names right
      chartMax: 600,                                // px: the chart stops growing here; the stream box takes the rest
      iconScale: 1.2,                               // icon width / seal radius
      stripSeal: 11,                                // seal radius in the folded strip
    },
    timing: {
      // ms; display pacing only — the final state is always the truth
      hold: 1600 / x, minOn: 1200 / x, pace: 700 / x, paceDone: 220 / x,
      pulse: 450 / Math.min(x, 2), pop: 1900 / Math.min(x, 2),
      tick: 100,                                    // at most 10 updates a second; nothing is redrawn unless it changed
      fold: 450, maxCards: 60,                      // the stream box keeps this many clauses; it scrolls inside itself
    },
    speed: x,
  };
}

functions.eliTeamDemo:
function eliTeamDemo() {
  var team = {
    lead: { id: "RV", name: "Revise", role: "Lead agent", icon: "revise" },
    agents: [
      { id: "PB", name: "Playbook", role: "Colgate’s positions", icon: "book", senior: true },
      { id: "GD", name: "Guidance", role: "Team rules", icon: "compass", parent: "PB" },
      { id: "PC", name: "Precedent", role: "Past deals", icon: "columns", parent: "PB" },
      { id: "FB", name: "Fallbacks", role: "Next positions", icon: "branch", parent: "PB" },
      { id: "DR", name: "Drafter", role: "Writes the changes", icon: "nib" },
      { id: "PL", name: "Placement", role: "Where it lands", icon: "target", parent: "DR" },
      { id: "FM", name: "Formatting", role: "The doc’s look", icon: "pilcrow", parent: "DR" },
      { id: "PR", name: "Proofreader", role: "Checks our edits", icon: "magnifier" },
      { id: "DX", name: "Definitions", role: "Defined terms", icon: "quotes", parent: "PR" },
      { id: "XR", name: "Cross-refs", role: "Section numbers", icon: "link", parent: "PR" },
      { id: "CM", name: "Comments", role: "Explains changes", icon: "note" },
    ],
  };
  // per article: playbook helpers, drafting helpers, proofreading helpers, a note, and what each found
  var A = [
    { art: "Article 1 · Definitions", n: 1, pb: ["GD"], dr: ["PL"], pr: ["DX"], items: [
      ["GD", "§1.12 “Deliverables”", "rule", "Work product must be inside the definition"],
      ["PL", "§1.12 “Deliverables”", "revise", "Placed inside the definition, before “provided”", "", ", including all work product,"],
      ["DX", "§1.12 “Deliverables”", "check", "New wording used the same way in all 4 places"]] },
    { art: "Article 3 · Fees and payment", n: 3, pb: ["GD"], dr: ["PL"], cm: true, items: [
      ["GD", "§3.2 Payment", "locked", "Colgate policy requires net 90; changes need VP sign-off"],
      ["PL", "§3.2 Payment", "revise", "Both the words and the figure changed", "thirty (30)", "ninety (90)"],
      ["CM", "§3.2 Payment", "note", "“Colgate policy requires payment terms of net 90.”"]] },
    { art: "Article 4 · Term and termination", n: 4, pb: ["PC", "FB"], dr: ["PL", "FM"], pr: ["XR"], items: [
      ["PC", "§4.2 Termination for Convenience", "precedent", "We settled on 30 days’ notice in 5 of 6 deals"],
      ["FB", "§4.2 Termination for Convenience", "fallback", "If they push back: 45 days’ notice, no approval needed"],
      ["FM", "§4.2 Termination for Convenience", "revise", "Run-in heading and numbering kept", "sixty (60)", "thirty (30)"],
      ["XR", "§4.2 Termination for Convenience", "check", "Its cross-reference to §4.5 still points to the right clause"]] },
    { art: "Article 6 · Intellectual property", n: 6, pb: ["GD"], dr: ["PL"], pr: ["DX"], items: [
      ["GD", "§6.1 Ownership", "rule", "Colgate owns all Deliverables on creation"],
      ["PL", "§6.1 Ownership", "insert", "New sentence placed at the end of §6.1", "", "All Deliverables are works made for hire and are owned by Colgate on creation."],
      ["DX", "§6.1 Ownership", "check", "“Deliverables” matches its definition in §1.12"]] },
    { art: "Article 7 · Confidentiality", n: 7, pb: [], dr: ["FM"], items: [
      ["FM", "§7.4 Return of Information", "revise", "Small capitals in the heading kept", "", "or destroy"]] },
    { art: "Article 9 · Indemnification", n: 9, pb: ["GD", "FB"], dr: ["PL"], cm: true, items: [
      ["GD", "§9.1 Indemnity", "locked", "A mutual indemnity needs Legal sign-off; left one-way"],
      ["FB", "§9.1 Indemnity", "fallback", "If they push back: mutual, capped at fees, with Legal sign-off"],
      ["PL", "§9.1 Indemnity", "revise", "Placed in the first sentence only", "use reasonable efforts to", ""],
      ["CM", "§9.1 Indemnity", "note", "“Colgate keeps indemnities one-way for services agreements.”"]] },
    { art: "Article 10 · Limitation of liability", n: 10, pb: ["PC", "FB"], dr: ["PL", "FM"], items: [
      ["PC", "§10.2 Cap", "precedent", "12 months’ fees in 7 of our last 9 deals"],
      ["FB", "§10.2 Cap", "fallback", "If they push back: 9 months’ fees with VP approval"],
      ["FM", "§10.2 Cap", "revise", "Number style matches the rest of the agreement", "three (3)", "twelve (12)"]] },
    { art: "Article 12 · Insurance", n: 12, pb: [], dr: ["PL"], pr: ["XR"], items: [
      ["PL", "§12.1 Coverage", "insert", "Added as a new item (d), list style kept", "", "(d) cyber liability insurance of not less than $5,000,000 per claim;"],
      ["XR", "§12.1 Coverage", "fix", "6 cross-references renumbered after the insertion", "Section 12.1(c)", "Section 12.1(d)"]] },
    { art: "Article 14 · General", n: 14, pb: ["PC"], dr: [], items: [
      ["PC", "§14.3 Governing Law", "keep", "New York, as in 11 prior deals; no change needed"]] },
  ];
  var ev = [], S = 1000;
  function on(agent, a, b, label) { ev.push({ at: a * S, agent: agent, phase: "start", label: label }); ev.push({ at: b * S, agent: agent, phase: "end" }); }
  function find(agent, at, art, it) {
    ev.push({ at: at * S, agent: agent, phase: "item", item: { art: art, clause: it[1], status: it[2], text: it[3], del: it[4] || "", ins: it[5] || "" } });
  }
  on("RV", 0, 2.2, "Reading the agreement · 42 pages");
  find("RV", 1.9, "The agreement", ["RV", "Master Services Agreement", "read", "42 pages · 14 articles · 9 need changes"]);
  var T0 = 2.6, STEP = 3.1, last = 0;
  A.forEach(function (a, i) {
    var p0 = T0 + i * STEP, ends = {};
    var art = "Article " + a.n;
    on("PB", p0, p0 + 2.9, "Checking " + art + " against the playbook");
    a.pb.forEach(function (c, k) { on(c, p0 + .3 + k * 1.3, ends[c] = p0 + 1.45 + k * 1.3, c === "GD" ? "Applying team rules to " + art : c === "PC" ? "Finding what we settled for in " + art : "Lining up the next position for " + art); });
    if (a.dr.length) {
      var d0 = p0 + 2;
      on("DR", d0, d0 + 2.9, "Revising " + art);
      a.dr.forEach(function (c, k) { on(c, d0 + .3 + k * 1.3, ends[c] = d0 + 1.45 + k * 1.3, c === "PL" ? "Placing the changes in " + art : "Keeping " + art + " in the document’s own look"); });
    }
    var q0 = p0 + 4;
    on("PR", q0, q0 + 2.9, "Proofreading " + art);
    (a.pr || []).forEach(function (c, k) { on(c, q0 + .4 + k * 1.3, ends[c] = q0 + 1.55 + k * 1.3, c === "DX" ? "Checking defined terms in " + art : "Checking cross-references in " + art); });
    if (a.cm) on("CM", q0 + 1.4, ends.CM = q0 + 3.2, "Writing a note on " + art);
    a.items.forEach(function (it) { find(it[0], ends[it[0]], a.art, it); });
    last = Math.max(last, q0 + 3.2);
  });
  var T = last + .3;
  on("PR", T, T + 2.6, "A last pass over the whole draft");
  on("DX", T + .3, T + 1.2, "Checking every defined term");
  on("XR", T + 1.4, T + 2.3, "Checking every cross-reference");
  T += 2.9;
  on("RV", T, T + 1.7, "Checking the whole draft and signing off");
  ev.push({ at: (T + 1.7) * S, phase: "done" });
  var PAUSE_AT = (T0 + 4 * STEP + .2) * S, PAUSE = 4 * S;
  ev.forEach(function (e) { if (e.at > PAUSE_AT) e.at += PAUSE; });
  ev.push({ at: PAUSE_AT, phase: "fold", label: "Waiting for you · 2 clauses to confirm" });
  ev.push({ at: PAUSE_AT + PAUSE, phase: "unfold" });
  ev.push({ at: (T + 1.7) * S + PAUSE + 600, phase: "finish", summary: {
    headline: "Done: 9 changes in 7 clauses",
    needsYou: [
      { clause: "§3.2 Payment", text: "Locked: net 90 needs VP sign-off before you send" },
      { clause: "§9.1 Indemnity", text: "Locked: confirm the one-way indemnity with Legal" },
    ] } });
  ev.sort(function (x, y) { return x.at - y.at; });
  return { team: team, eyebrow: "Revise document · demo", title: "Master Services Agreement · 42 pp", events: ev };
}

engine.eliTeamModel:
function eliTeamModel(team, tokens) {
  var tm = tokens && tokens.timing || {};
  var HOLD = tm.hold || 1600, MIN_ON = tm.minOn || 1200, PULSE = tm.pulse || 450, POP = tm.pop == null ? 1900 : tm.pop,
    PACE = tm.pace || 700, PACE_DONE = tm.paceDone || 220, MAX_CARDS = tm.maxCards || 6;
  var STATUS = {
    revise: ["Revised", "rev"], insert: ["Inserted", "rev"], fix: ["Fixed", "rev"], locked: ["Locked", "lock"],
    note: ["Note", ""], keep: ["No change", ""], check: ["Checked", ""], precedent: ["Precedent", ""],
    fallback: ["Fallback", ""], rule: ["Rule", ""], read: ["Read", ""], done: ["Done", ""],
  };
  var POPTEXT = {
    revise: "Change made", insert: "New text placed", fix: "Fixed", locked: "Locked clause", note: "Note written",
    keep: "No change needed", check: "Checked", precedent: "Precedent found", fallback: "Fallback ready",
    rule: "Team rule found", read: "Document read",
  };
  var REVISION = { revise: 1, insert: 1, fix: 1 };

  var lead = team && team.lead ? team.lead : { id: "LD", name: "Lead" };
  var nodes = [{ id: lead.id, name: lead.name || lead.id, role: lead.role || "Lead agent", icon: lead.icon || "", senior: false, parent: null, lv: 0 }];
  var byId = {};
  byId[lead.id] = nodes[0];
  (team && team.agents || []).forEach(function (a) {
    if (!a || !a.id || byId[a.id]) return;
    var n = { id: a.id, name: a.name || a.id, role: a.role || "", icon: a.icon || "", senior: !!a.senior, parent: a.parent || lead.id, lv: 1 };
    nodes.push(n); byId[a.id] = n;
  });
  nodes.forEach(function (n) {
    if (n.lv === 0) return;
    if (!byId[n.parent] || n.parent === n.id) n.parent = lead.id;
    n.lv = n.parent === lead.id ? 1 : 2;
    if (n.lv === 2 && byId[n.parent].lv !== 1) { n.parent = lead.id; n.lv = 1; } // three levels at most
  });

  var runs = {}, labels = {}, items = [], t0 = null, doneAt = null, summary = null;
  nodes.forEach(function (n) { runs[n.id] = []; });

  function closeAll(at) { nodes.forEach(function (n) { runs[n.id].forEach(function (x) { if (x[1] == null) x[1] = Math.max(at, x[0]); }); }); }
  function event(ev) {
    if (!ev || typeof ev.at !== "number") return false;
    if (t0 == null) t0 = ev.at;
    if (ev.phase === "done") { if (doneAt == null) { doneAt = ev.at; summary = ev.summary || null; closeAll(ev.at); } return true; }
    var id = ev.agent;
    if (!byId[id]) return false;
    var r = runs[id];
    if (ev.phase === "start") {
      if (!(r.length && r[r.length - 1][1] == null)) r.push([ev.at, null]);
      if (ev.label) labels[id] = ev.label;
      return true;
    }
    if (ev.phase === "end") {
      for (var i = r.length - 1; i >= 0; i--) if (r[i][1] == null) { r[i][1] = Math.max(ev.at, r[i][0]); break; }
      return true;
    }
    if (ev.phase === "item" && ev.item) { items.push({ agent: id, arrived: ev.at, item: ev.item }); return true; }
    return false;
  }

  // display stretches: each burst held at least MIN_ON, bursts closer than HOLD read as one
  // an agent works through its steps and, briefly, as each of its findings is revealed (assistants often send only findings)
  function spans(id, now, shown) {
    var out = [], all = runs[id].map(function (x) { return [x[0], x[1], 1]; });
    if (shown) items.forEach(function (x, i) { if (x.agent === id && shown[i] <= now) all.push([shown[i], shown[i], 0]); });
    all.sort(function (p, q) { return p[0] - q[0]; });
    all.forEach(function (x) {
      var a = x[0], b = x[1] == null ? Math.max(now, a + MIN_ON) : Math.max(x[1], a + MIN_ON);
      var last = out[out.length - 1];
      if (last && a - last[1] < HOLD) { last[1] = Math.max(last[1], b); last[2] = last[2] || x[2]; } else out.push([a, b, x[2]]);
    });
    return out;
  }
  // findings reveal at a readable pace; once the run is done the backlog clears quickly
  function shownTimes() {
    var prev = -Infinity;
    return items.map(function (x) {
      var gap = doneAt != null && prev + PACE > doneAt ? PACE_DONE : PACE;
      prev = Math.max(x.arrived, prev + gap);
      return prev;
    });
  }

  // the agent most recently given work — a step starting, or a finding as it is revealed (paced, so a burst from several
  // agents calls each in turn); deepest wins a tie. A return to an agent after another counts as a new call.
  function lastCalled(now, shown) {
    var best = null;
    function consider(id, at) { if (at <= now && (!best || at > best.at || (at === best.at && byId[id].lv > byId[best.id].lv))) best = { id: id, at: at }; }
    nodes.forEach(function (n) { if (n.lv > 0) runs[n.id].forEach(function (x) { consider(n.id, x[0]); }); });
    items.forEach(function (x, i) { if (byId[x.agent].lv > 0) consider(x.agent, shown[i]); });
    return best;
  }

  function snapshot(now) {
    if (t0 == null) t0 = now;
    var shown = shownTimes();
    var pending = shown.filter(function (s) { return s > now; }).length;
    var finished = doneAt != null && now >= doneAt && pending === 0;
    var states = {}, pulses = [], focus = null, focusStart = -Infinity;
    var found = {};
    items.forEach(function (x) { found[x.agent] = 1; });
    nodes.forEach(function (n) {
      var worked = runs[n.id].length || found[n.id];
      var st = worked ? "lit" : "idle";
      spans(n.id, now, shown).forEach(function (s) {
        if (now >= s[0] && now < s[1] && !finished) {
          st = "active";
          if (n.lv > 0 && s[2] && (s[0] > focusStart || (s[0] === focusStart && n.lv > byId[focus].lv))) { focus = n.id; focusStart = s[0]; }
        }
        if (n.lv > 0 && now >= s[0] && now - s[0] < PULSE) pulses.push({ to: n.id, p: (now - s[0]) / PULSE });
      });
      if (finished && worked) st = "done";
      if (n.lv === 0 && st === "lit" && doneAt == null) st = "lead";
      states[n.id] = st;
    });
    if (!focus) { // a gap between steps: keep naming the step that started most recently
      var latest = -Infinity;
      nodes.forEach(function (n) { runs[n.id].forEach(function (x) { if (x[0] <= now && x[0] >= latest && (x[0] > latest || n.lv > byId[focus || n.id].lv)) { latest = x[0]; focus = n.id; } }); });
      if (!focus || finished) focus = nodes[0].id;
    }
    var path = []; for (var c = focus; c; c = byId[c].parent) path.unshift(c);

    var cards = [], byKey = {}, revisions = 0, pop = null, byAgent = {};
    items.forEach(function (x, i) {
      if (shown[i] > now) return;
      var it = x.item, key = (it.art || "") + "|" + (it.clause || "");
      var card = byKey[key];
      if (!card) { card = byKey[key] = { key: key, art: it.art || "", clause: it.clause || "", first: shown[i], last: shown[i], statuses: [], lines: [] }; cards.push(card); }
      card.last = shown[i];
      if (it.status) card.statuses.push(it.status);
      card.lines.push({ id: key + "#" + i, agent: x.agent, text: it.text || "", del: it.del || "", ins: it.ins || "", shownAt: shown[i] });
      if (REVISION[it.status]) revisions++;
      (byAgent[x.agent] = byAgent[x.agent] || []).push({ clause: it.clause || "", text: it.text || "", status: it.status || "" });
      if (POP && now - shown[i] < POP) pop = { id: i, agent: x.agent, text: it.pop || POPTEXT[it.status] || "Done", age: now - shown[i] };
    });
    cards.sort(function (a, b) { return b.first - a.first; });
    cards = cards.slice(0, MAX_CARDS).map(function (c) {
      var chips = [], s = c.statuses;
      if (s.indexOf("locked") >= 0) chips.push(STATUS.locked);
      var rv = ["revise", "insert", "fix"].filter(function (k) { return s.indexOf(k) >= 0; })[0];
      if (rv) chips.push(STATUS[rv]);
      if (!chips.length && s.length) chips.push(STATUS[s[s.length - 1]] || [s[s.length - 1], ""]);
      return { key: c.key, art: c.art, clause: c.clause, chips: chips, at: c.last - t0, lines: c.lines };
    });

    return {
      elapsed: Math.max(0, (doneAt != null ? Math.min(now, doneAt) : now) - t0),
      done: finished,
      nodes: nodes.map(function (n) { return { id: n.id, name: n.name, role: n.role, icon: n.icon, senior: n.senior, parent: n.parent, lv: n.lv, state: states[n.id] }; }),
      pulses: pulses, pop: pop, called: lastCalled(now, shown),
      focus: { id: focus, path: path, label: finished ? "Team signed off" : labels[focus] || byId[focus].role || byId[focus].name },
      cards: cards, pending: pending, byAgent: byAgent,
      revisions: summary && typeof summary.revisions === "number" ? summary.revisions : revisions,
    };
  }

  return { event: event, snapshot: snapshot };
}

view.eliTeamView:
function eliTeamView(mount, opts) {
  opts = opts || {};
  var TK = opts.tokens, C = TK.color, Z = TK.size, TM = TK.timing, CLOCK = opts.clockScale || 1;
  var RM = !!(window.matchMedia && window.matchMedia("(prefers-reduced-motion: reduce)").matches);
  var SVGNS = "http://www.w3.org/2000/svg", UID = "et" + Math.random().toString(36).slice(2, 8);

  function el(tag, cls, text) { var n = document.createElement(tag); if (cls) n.className = cls; if (text != null) n.textContent = text; return n; }
  function sv(tag, attrs, cls) { var n = document.createElementNS(SVGNS, tag); for (var k in attrs || {}) n.setAttribute(k, attrs[k]); if (cls) n.setAttribute("class", cls); return n; }
  function esc(s) { return String(s == null ? "" : s).replace(/&/g, "&amp;").replace(/</g, "&lt;").replace(/>/g, "&gt;").replace(/"/g, "&quot;"); }
  function fmt(ms) { var s = Math.floor(ms / 1000); return Math.floor(s / 60) + ":" + String(s % 60).padStart(2, "0"); }
  function setClass(n, cls, on) { if (n.classList.contains(cls) !== !!on) n.classList.toggle(cls, !!on); }
  function setText(n, t) { if (n.textContent !== t) n.textContent = t; }

  // ─── shell: tokens become CSS variables, so style.css holds no colours ───
  var root = el("div", "et et-" + TK.theme + " is-prelude " + UID);
  var VARS = { panel: C.panel, surface: C.surface, ink: C.ink, mute: C.mute, faint: C.faint, line: C.line, navy: C.navy, "navy-top": C.navyTop,
    "navy-bottom": C.navyBottom, gold: C.gold, "gold-pale": C.goldPale, "gold-ink": C.goldInk, "idle-fill": C.idleFill, tint: C.tint,
    shadow: C.shadow, pop: C.pop, prop: C.prop, "prop-fill": C.propFill, "prop-del": C.propDel, "prop-del-fill": C.propDelFill, "chart-glow": C.chartGlow, fold: TM.fold + "ms" };
  for (var v in VARS) root.style.setProperty("--et-" + v, VARS[v]);
  // each drawing (chart, strip, prelude) has its own gradients: a url(#…) that names a hidden drawing's gradient paints nothing
  function defs(k) {
    return '<defs><radialGradient id="' + UID + k + '-gl"><stop offset="0" style="stop-color:var(--et-gold);stop-opacity:.32"/><stop offset="1" style="stop-color:var(--et-gold);stop-opacity:0"/></radialGradient>'
      + '<linearGradient id="' + UID + k + '-nv" x1="0" y1="0" x2="0" y2="1"><stop offset="0" style="stop-color:var(--et-navy-top)"/><stop offset=".55" style="stop-color:var(--et-navy)"/><stop offset="1" style="stop-color:var(--et-navy-bottom)"/></linearGradient></defs>';
  }

  // prelude: the lead alone, breathing, before the team starts
  var pre = el("div", "et-pre"), preSvg = sv("svg", { viewBox: "0 0 120 120" }, "et-presvg");
  var preLabel = el("div", "et-prelabel", opts.preludeLabel || "Getting ready"), preBar = el("div", "et-shimmer");
  pre.appendChild(preSvg); pre.appendChild(preLabel); pre.appendChild(preBar);
