    detailsBtn.hidden = summary.details === false;
    setText(stripNote, "Tap an agent to see what it found");
  }
  function destroy() { if (root.parentNode) root.parentNode.removeChild(root); }

  // the prelude's stage: the lead, and the specialists waiting (unseen) in a row beneath it until their role is named
  var PRE = {}, preSpecs = ((opts.team && opts.team.agents) || []).filter(function (a) { return !a.parent || a.parent === (opts.team.lead || {}).id; });
